window.ADVENT_ITEMS=[{"id":"selfcare-01","category":"selfcare","budget":"none","kind":"do","title":"Ten minutes at the window","detail":"Sit by a window for ten minutes with your phone in another room. Watch the winter light change and let your mind wander."},{"id":"selfcare-02","category":"selfcare","budget":"none","kind":"think","title":"What can you put down this season?","detail":"Name one holiday task you do out of habit, not joy. Could you simplify it, share it, or skip it this year?"},{"id":"selfcare-03","category":"selfcare","budget":"none","kind":"do","title":"A warm bath with a towel pillow","detail":"Run a warm bath, roll a towel behind your neck, and stay until the water cools. Dim the lights if you can."},{"id":"selfcare-04","category":"selfcare","budget":"none","kind":"do","title":"Five minute shoulder release","detail":"Roll your shoulders back ten times, then forward ten. Tilt each ear toward a shoulder for one slow breath. Repeat twice."},{"id":"selfcare-05","category":"selfcare","budget":"none","kind":"think","title":"Three small wins from this week","detail":"Say or write three things that went fine this week, even tiny ones like a hot coffee or a green light."},{"id":"selfcare-06","category":"selfcare","budget":"none","kind":"do","title":"Go to bed 45 minutes early","detail":"Lay out tomorrow's clothes first so your mind has nothing left to rehearse. Then lights out a little ahead of schedule."},{"id":"selfcare-07","category":"selfcare","budget":"none","kind":"do","title":"Warm socks and a quiet hour","detail":"Put on your warmest socks, pile on a blanket, and spend one hour on something that asks nothing of you."},{"id":"selfcare-08","category":"selfcare","budget":"none","kind":"read","title":"A note to yourself","detail":"Write a short, kind note to yourself, the way you would to a tired friend. Fold it and tuck it in a coat pocket to find later."},{"id":"selfcare-09","category":"selfcare","budget":"none","kind":"do","title":"Box breathing by the lights","detail":"Sit near the tree or any glowing lights. Breathe in for four counts, hold four, out four, hold four. Do six rounds."},{"id":"selfcare-10","category":"selfcare","budget":"none","kind":"think","title":"What does rest look like for you?","detail":"Is it a nap, a walk, a book, or silence? Pick one version of rest and put it on this week's calendar."},{"id":"selfcare-11","category":"selfcare","budget":"none","kind":"do","title":"Two minute hand massage","detail":"Using any lotion or none, press your palm with your thumb, then gently pull and squeeze each finger. Switch hands."},{"id":"selfcare-12","category":"selfcare","budget":"none","kind":"do","title":"Clear one small spot","detail":"Tidy one drawer, shelf, or corner of the counter in fifteen minutes. Stop when the timer rings, even if it is half done."},{"id":"selfcare-13","category":"selfcare","budget":"none","kind":"read","title":"A winter permission slip","detail":"\"You may do less. You may say no kindly. You may leave the party when your heart says so.\" Copy it on a sticky note."},{"id":"selfcare-14","category":"selfcare","budget":"none","kind":"do","title":"Five minutes of stargazing","detail":"Bundle up, step outside after dark, and look up for five minutes. Find the brightest thing in the sky and just watch it."},{"id":"selfcare-15","category":"selfcare","budget":"none","kind":"think","title":"Who made you feel welcome this year?","detail":"Think of one person who made you feel at ease. Decide how to thank them, even if it is a two line text."},{"id":"selfcare-16","category":"selfcare","budget":"none","kind":"do","title":"Gentle eye reset","detail":"Warm your palms and cup them over closed eyes for one minute. Then gaze at something far out the window for twenty seconds."},{"id":"selfcare-17","category":"selfcare","budget":"none","kind":"do","title":"Unplug for one evening hour","detail":"Turn off the TV and silence notifications for one hour after dinner. Fill it with whatever feels slower."},{"id":"selfcare-18","category":"selfcare","budget":"none","kind":"do","title":"Fluff and fold the bed","detail":"Straighten the bed, plump the pillows, and add one extra blanket. Getting in tonight is the reward."},{"id":"selfcare-19","category":"selfcare","budget":"none","kind":"think","title":"One tradition to keep, one to drop","detail":"Pick a holiday habit you truly love and one you could retire. Tell someone which is which."},{"id":"selfcare-20","category":"selfcare","budget":"none","kind":"do","title":"One slow warm drink","detail":"Make any warm drink and finish it sitting down with no screen. Notice the smell, the steam, and the first sip."},{"id":"selfcare-21","category":"selfcare","budget":"none","kind":"do","title":"Write a worry list, then close it","detail":"List everything on your mind on one page. Fold it, put it in a drawer, and tell yourself it can wait until after the holidays."},{"id":"selfcare-22","category":"selfcare","budget":"none","kind":"do","title":"Floor stretch with legs up","detail":"Lie on a rug, hug your knees, and rock gently side to side. Finish with your calves resting on a chair seat for two minutes."},{"id":"selfcare-23","category":"selfcare","budget":"none","kind":"think","title":"What do you want more of in January?","detail":"Name one feeling (calm, energy, connection) and one tiny habit that could invite it. Jot both down."},{"id":"selfcare-24","category":"selfcare","budget":"none","kind":"do","title":"Sing while you wash up","detail":"Pick a favorite song and sing it at any volume while you do the dishes. Enthusiasm counts more than pitch."},{"id":"selfcare-25","category":"selfcare","budget":"low","kind":"do","title":"A new bath bomb or salts","detail":"Pick up bath salts or a fizzy bath bomb in a scent you love, then take a long soak with the door closed."},{"id":"selfcare-26","category":"selfcare","budget":"low","kind":"do","title":"Fresh flowers or a pine bundle","detail":"Buy a small bunch of flowers or a few evergreen sprigs and put them where you will see them every morning."},{"id":"selfcare-27","category":"selfcare","budget":"low","kind":"do","title":"A scented candle for your chair","detail":"Choose a candle that smells like winter to you, such as cedar, orange, or vanilla, and light it during your quiet time."},{"id":"selfcare-28","category":"selfcare","budget":"low","kind":"do","title":"Face mask and cucumber eyes","detail":"Use a sheet mask or a simple clay mask, and rest with cool cucumber slices on your eyes for ten minutes."},{"id":"selfcare-29","category":"selfcare","budget":"low","kind":"do","title":"A good pen and a blank journal","detail":"Buy a notebook and a pen that feels smooth. Write three lines tonight, about anything at all."},{"id":"selfcare-30","category":"selfcare","budget":"low","kind":"do","title":"Real hand cream and a long rub","detail":"Buy a hand cream you like the smell of. Warm it between your palms and take your time with each finger."},{"id":"selfcare-31","category":"selfcare","budget":"low","kind":"do","title":"Home manicure session","detail":"Buy a polish or a nail file and buffer and give yourself a ten minute manicure while a favorite album plays."},{"id":"selfcare-32","category":"selfcare","budget":"low","kind":"do","title":"A sleep mask and early night","detail":"Pick up a soft sleep mask. Wear it tonight with the room dark and the phone out of reach."},{"id":"selfcare-33","category":"selfcare","budget":"low","kind":"do","title":"Slippers that feel like a hug","detail":"Treat your feet to a pair of soft, warm slippers and wear them straight through the weekend."},{"id":"selfcare-34","category":"selfcare","budget":"low","kind":"do","title":"Pick up a new lip balm set","detail":"Buy a tin of lip balm or a small body butter in a seasonal scent, and tuck one in each coat pocket."},{"id":"selfcare-35","category":"selfcare","budget":"medium","kind":"do","title":"A short massage or chair massage","detail":"Book a 30 minute massage or a chair massage at a salon. Go in with no plans for the rest of the afternoon."},{"id":"selfcare-36","category":"selfcare","budget":"medium","kind":"do","title":"A weighted or heated blanket","detail":"Treat yourself to a weighted or heated throw blanket for the couch. Try it out with a book and a warm drink."},{"id":"selfcare-37","category":"selfcare","budget":"medium","kind":"do","title":"A pedicure for winter feet","detail":"Book a pedicure and let someone else handle the scrubbing and the polish. Pick a color that surprises you."},{"id":"selfcare-38","category":"selfcare","budget":"medium","kind":"do","title":"A proper haircut or blowout","detail":"Book a trim or style at a salon you like. Ask for one change that makes mornings easier."},{"id":"selfcare-39","category":"selfcare","budget":"medium","kind":"do","title":"A facial or skin treatment","detail":"Book a facial or buy a good skin set you have been eyeing. Plan an evening to use it with no rushing."},{"id":"selfcare-40","category":"selfcare","budget":"medium","kind":"do","title":"A cozy robe you will actually wear","detail":"Buy a soft robe or lounge set and put it on the minute you get home tomorrow."},{"id":"selfcare-41","category":"selfcare","budget":"high","kind":"do","title":"A 90 minute massage","detail":"Book a full 90 minute massage and arrive ten minutes early to sit and breathe. Plan a quiet evening afterward."},{"id":"selfcare-42","category":"selfcare","budget":"high","kind":"do","title":"A half day at a spa","detail":"Book a spa half day with a soak, a treatment, and time in the quiet room. Turn your phone off at the door."},{"id":"selfcare-43","category":"selfcare","budget":"high","kind":"do","title":"One night at a nearby hotel","detail":"Book a single night in a hotel within driving distance, with room service or a long breakfast. Sleep in on purpose."},{"id":"selfcare-44","category":"selfcare","budget":"high","kind":"do","title":"A wellness weekend away","detail":"Plan two nights at a cabin, inn, or retreat with nothing scheduled except walks, naps, and reading by a fire."},{"id":"family-01","category":"family","budget":"none","kind":"do","title":"Paper snowflake contest","detail":"Fold and cut paper snowflakes, tape them to a window, and vote on the most detailed one. Give every person a prize category."},{"id":"family-02","category":"family","budget":"none","kind":"think","title":"Our favorite holiday memory","detail":"Go around the table and share a favorite memory from any year. Everyone asks one follow up question."},{"id":"family-03","category":"family","budget":"none","kind":"do","title":"Living room campout","detail":"Drag blankets and pillows into the living room, switch off the big lights, and spend the evening there with flashlights."},{"id":"family-04","category":"family","budget":"none","kind":"do","title":"Holiday charades","detail":"Write holiday words on slips (sleigh, mittens, snowman) and act them out silently in teams. Ten words per team."},{"id":"family-05","category":"family","budget":"none","kind":"do","title":"Story chain by the tree","detail":"Open with \"On the coldest night of the year...\" and add one sentence each. Keep going until the story ends itself."},{"id":"family-06","category":"family","budget":"none","kind":"do","title":"Call a faraway relative","detail":"Phone or video call someone you have not talked to in a while. Each person shares one thing they like about them."},{"id":"family-07","category":"family","budget":"none","kind":"think","title":"Our family in three words","detail":"Everyone picks three words that describe your family this year. Compare lists and talk about the surprises."},{"id":"family-08","category":"family","budget":"none","kind":"do","title":"Flashlight hide and seek","detail":"Clear the room first, then play hide and seek in a dim house with a flashlight for the seeker. Short rounds work best."},{"id":"family-09","category":"family","budget":"none","kind":"do","title":"Thank you notes for helpers","detail":"Each person writes a note to someone who helps them, like a teacher, mail carrier, or neighbor. Deliver them by hand."},{"id":"family-10","category":"family","budget":"none","kind":"do","title":"Interview an older relative","detail":"Ask five questions about their childhood winters. Record the answers on a phone or write them down in a notebook."},{"id":"family-11","category":"family","budget":"none","kind":"do","title":"Hang the kid art","detail":"String yarn or tape across a wall and hang drawings like a garland. Let the youngest decide the order."},{"id":"family-12","category":"family","budget":"none","kind":"do","title":"Two truths and a holiday lie","detail":"Each person tells three holiday stories, two real and one invented. Everyone else guesses the fib."},{"id":"family-13","category":"family","budget":"none","kind":"do","title":"A lights walk after dinner","detail":"Walk the neighborhood after dark and give points for best display. Tally the scores on the way home."},{"id":"family-14","category":"family","budget":"none","kind":"think","title":"Our family holiday motto","detail":"Work together to write a one line motto for this season, then write it on a card and prop it on the table."},{"id":"family-15","category":"family","budget":"none","kind":"do","title":"Fill a family time capsule","detail":"Each person writes a note, a prediction, and a favorite thing from this year. Seal them in a box to open next December."},{"id":"family-16","category":"family","budget":"none","kind":"do","title":"Sock skating relay","detail":"On a smooth floor with furniture pushed aside, glide in socks to a marker and back. Slow and silly wins."},{"id":"family-17","category":"family","budget":"none","kind":"do","title":"Family card tournament","detail":"Pick a card game everyone knows, play best of three, and crown a champion with a paper crown."},{"id":"family-18","category":"family","budget":"none","kind":"do","title":"Swap chores for a day","detail":"Everyone does one job usually done by someone else. Share at dinner what turned out to be harder than it looked."},{"id":"family-19","category":"family","budget":"none","kind":"think","title":"Finish: I feel loved when","detail":"Everyone finishes that sentence on sticky notes. Post them on the fridge for the rest of the month."},{"id":"family-20","category":"family","budget":"none","kind":"do","title":"Shadow puppet show","detail":"In a dim room with a lamp, make hand shadows on the wall and act out a short winter story together."},{"id":"family-21","category":"family","budget":"none","kind":"do","title":"Look through old photos","detail":"Pull out an album or scroll old phone photos together. Each person picks a favorite and tells why."},{"id":"family-22","category":"family","budget":"none","kind":"do","title":"A secret kindness for a neighbor","detail":"Bring in their bins, sweep their steps, or leave a kind note on the door. Do not sign it."},{"id":"family-23","category":"family","budget":"none","kind":"do","title":"Holiday trivia night","detail":"Everyone writes five questions about family history or holiday customs. Take turns quizzing, one point per right answer."},{"id":"family-24","category":"family","budget":"none","kind":"do","title":"Hide kind notes","detail":"Each person tucks a short encouraging note where someone else will find it, like a coat pocket, shoe, or lunch bag."},{"id":"family-25","category":"family","budget":"low","kind":"do","title":"Try a brand new board game","detail":"Pick up an inexpensive family game nobody has played. Read the rules out loud together and play one full round."},{"id":"family-26","category":"family","budget":"low","kind":"do","title":"Glow stick dance party","detail":"Grab a pack of glow sticks, turn the lights off, and dance to three songs picked by three different people."},{"id":"family-27","category":"family","budget":"low","kind":"do","title":"One disposable camera each","detail":"Hand out cheap disposable or simple cameras and snap an evening of unposed photos. Develop them for a surprise."},{"id":"family-28","category":"family","budget":"low","kind":"do","title":"Print and frame a favorite photo","detail":"Print one photo you all love at a drugstore kiosk and pop it into a cheap frame for the mantel."},{"id":"family-29","category":"family","budget":"low","kind":"do","title":"Paint your own ornaments","detail":"Buy plain wooden or ceramic ornaments and paint one each. Date them on the back so you can look back in years."},{"id":"family-30","category":"family","budget":"low","kind":"do","title":"Five dollar Secret Santa","detail":"Draw names and set a five dollar limit. The best gift usually comes from imagination, not money."},{"id":"family-31","category":"family","budget":"low","kind":"do","title":"A dollar store treasure hunt","detail":"Hide a few small prizes and write clues in rhyme. Adults read the clues, kids hunt."},{"id":"family-32","category":"family","budget":"low","kind":"do","title":"Donate a gift to a toy drive","detail":"Each person picks one new toy or book to buy for a drive, and you drop it off together."},{"id":"family-33","category":"family","budget":"low","kind":"do","title":"Cards for far away friends","detail":"Buy a pack of cards and stamps, and let each person write to someone they miss. Walk them to the mailbox together."},{"id":"family-34","category":"family","budget":"low","kind":"do","title":"Family hat day","detail":"Pick up cheap Santa hats or knit caps for everyone and wear them through dinner, errands, and chores."},{"id":"family-35","category":"family","budget":"medium","kind":"do","title":"Family bowling or mini golf","detail":"Book a lane or a round and keep a score sheet. Give a prize for best trick shot and worst gutter ball."},{"id":"family-36","category":"family","budget":"medium","kind":"do","title":"A holiday train or lights ride","detail":"Find a local holiday train, hay ride, or light show and make an evening of it with warm coats."},{"id":"family-37","category":"family","budget":"medium","kind":"do","title":"A trip to the arcade or trampoline park","detail":"Set a budget, hand out tokens, and play for an hour. Let kids choose the first game and adults the last."},{"id":"family-38","category":"family","budget":"medium","kind":"do","title":"A tree farm or wreath workshop","detail":"Pick a tree or make a wreath together at a farm or garden center. Take a family photo with the finished piece."},{"id":"family-39","category":"family","budget":"medium","kind":"do","title":"A family movie at the theater","detail":"See a cozy film on the big screen, popcorn included. Ask everyone to pick their favorite scene afterward."},{"id":"family-40","category":"family","budget":"medium","kind":"do","title":"A pottery painting afternoon","detail":"Visit a paint your own pottery studio and make a gift or keepsake for each other. Pick up the pieces after they are fired."},{"id":"family-41","category":"family","budget":"high","kind":"do","title":"A family photo session","detail":"Book a photographer for a seasonal family portrait. Let the whole family vote on outfits and the location."},{"id":"family-42","category":"family","budget":"high","kind":"do","title":"A Nutcracker or holiday show","detail":"Buy tickets to a local ballet, concert, or holiday stage show and dress up a little for the evening."},{"id":"family-43","category":"family","budget":"high","kind":"do","title":"A cabin or lodge weekend","detail":"Rent a cabin or lodge for a weekend with games, cards, and a long breakfast. Leave the schedule open."},{"id":"family-44","category":"family","budget":"high","kind":"do","title":"A day trip to the snow","detail":"Drive to a snowy spot for sledding, snow play, and a picnic lunch in the car with the heater on."},{"id":"fitness-01","category":"fitness","budget":"none","kind":"do","title":"A ten minute cold air walk","detail":"Bundle up and walk around the block at an easy pace. Notice three things you only see in winter."},{"id":"fitness-02","category":"fitness","budget":"none","kind":"do","title":"Snow angel count","detail":"If there is snow, make snow angels and count how many each person can make in a row. No snow? Use a blanket on the lawn."},{"id":"fitness-03","category":"fitness","budget":"none","kind":"do","title":"Living room dance break","detail":"Play three upbeat songs and dance through them. Keep it fun and move however your body likes."},{"id":"fitness-04","category":"fitness","budget":"none","kind":"do","title":"Gentle morning stretch","detail":"Reach overhead, touch your toes gently, and do five slow side bends each way. Breathe through every one."},{"id":"fitness-05","category":"fitness","budget":"none","kind":"do","title":"March in place during a show","detail":"Each time a commercial or credit roll starts, march in place with high knees until it ends. Go easy on your joints."},{"id":"fitness-06","category":"fitness","budget":"none","kind":"do","title":"Stair climb challenge","detail":"Walk up and down your stairs five times at a steady pace. Add one trip each day this week if it feels good."},{"id":"fitness-07","category":"fitness","budget":"none","kind":"do","title":"Chair yoga series","detail":"Sit tall and do five gentle moves: neck rolls, shoulder circles, seated twist, ankle circles, and a forward fold."},{"id":"fitness-08","category":"fitness","budget":"none","kind":"do","title":"Walk and spot the lights","detail":"Walk the neighborhood and count the houses with lights. Try to beat your count tomorrow."},{"id":"fitness-09","category":"fitness","budget":"none","kind":"do","title":"Wall push ups, ten at a time","detail":"Stand an arm's length from a wall and do ten slow push ups, rest, and repeat twice. Keep your back straight."},{"id":"fitness-10","category":"fitness","budget":"none","kind":"do","title":"Balance on one foot","detail":"Brush your teeth standing on one foot, then switch. Hold a counter if you need to. Try for 30 seconds per side."},{"id":"fitness-11","category":"fitness","budget":"none","kind":"do","title":"Wrapping paper toss and catch","detail":"Crumple used wrapping paper into balls, then toss and catch them in pairs. Step back a pace each time you succeed."},{"id":"fitness-12","category":"fitness","budget":"none","kind":"do","title":"Indoor scavenger walk","detail":"Walk through the house finding five red things, five green things, and five shiny things. Keep a steady pace."},{"id":"fitness-13","category":"fitness","budget":"none","kind":"do","title":"Sit to stand strength","detail":"Stand up from a sturdy chair ten times without using your hands if possible. Rest, then do another ten."},{"id":"fitness-14","category":"fitness","budget":"none","kind":"do","title":"Snowball toss practice","detail":"Set a bucket across the yard and toss soft snowballs or rolled up socks at it. Keep score for each person."},{"id":"fitness-15","category":"fitness","budget":"none","kind":"do","title":"A stretch while the kettle boils","detail":"Use the wait to stretch calves against the counter and roll your neck. Turn it into a daily habit this week."},{"id":"fitness-16","category":"fitness","budget":"none","kind":"do","title":"Slow Santa pose flow","detail":"Reach tall like a chimney, bend down gently, then curl up like a sack of presents. Repeat the slow flow five times."},{"id":"fitness-17","category":"fitness","budget":"none","kind":"do","title":"Carry and lift in daily tasks","detail":"Carry laundry or groceries with a straight back and bent knees. Count it as a workout and stay safe."},{"id":"fitness-18","category":"fitness","budget":"none","kind":"do","title":"A twenty minute family walk","detail":"Pick a time everyone can join and set off at a pace where you can all chat. Share a favorite from the day."},{"id":"fitness-19","category":"fitness","budget":"none","kind":"do","title":"Gentle hip circles","detail":"Stand with feet apart and draw big slow circles with your hips, ten each direction. Hold a chair if you like."},{"id":"fitness-20","category":"fitness","budget":"none","kind":"do","title":"Dance with a broom","detail":"Pick up a broom as a dance partner and waltz around the kitchen. A great lower body warm up, with a smile."},{"id":"fitness-21","category":"fitness","budget":"none","kind":"do","title":"Calf raises at the sink","detail":"While rinsing dishes, rise onto your toes and lower slowly. Do twelve, rest, then do twelve more."},{"id":"fitness-22","category":"fitness","budget":"none","kind":"do","title":"Wiggle breaks every hour","detail":"Set a timer each hour today. When it rings, stand up, shake your arms and legs for thirty seconds, and sit back down."},{"id":"fitness-23","category":"fitness","budget":"none","kind":"do","title":"Balloon volleyball","detail":"Blow up a balloon and keep it off the floor as a team. See how many hits you can reach before it lands."},{"id":"fitness-24","category":"fitness","budget":"none","kind":"do","title":"Stretch before bed","detail":"Lie on your back and bring one knee to your chest, then the other. Finish with five deep belly breaths."},{"id":"fitness-25","category":"fitness","budget":"low","kind":"do","title":"Buy a jump rope","detail":"Pick up a jump rope for about ten dollars and try a few easy hops. Stop whenever you like."},{"id":"fitness-26","category":"fitness","budget":"low","kind":"do","title":"Resistance band routine","detail":"Buy a light resistance band and do arm pulls and leg presses while watching your favorite show. Keep reps slow."},{"id":"fitness-27","category":"fitness","budget":"low","kind":"do","title":"A yoga mat and ten minutes","detail":"Pick up an inexpensive yoga mat and follow a ten minute gentle video or sequence from a library book."},{"id":"fitness-28","category":"fitness","budget":"low","kind":"do","title":"Hand warmers and a long walk","detail":"Buy a pair of hand warmers and head for a longer walk than usual. Turn around when you feel like it."},{"id":"fitness-29","category":"fitness","budget":"low","kind":"do","title":"A reflective vest or light","detail":"Buy a reflective band or small clip light so you can walk safely after dark. Take a twenty minute stroll to try it."},{"id":"fitness-30","category":"fitness","budget":"low","kind":"do","title":"A used sled for the nearest hill","detail":"Find a used sled at a thrift store and haul it up a gentle hill. Keep the runs short and the laughs loud."},{"id":"fitness-31","category":"fitness","budget":"low","kind":"do","title":"Light hand weights","detail":"Buy a pair of one or two pound hand weights and do bicep curls and shoulder raises while watching a movie."},{"id":"fitness-32","category":"fitness","budget":"low","kind":"do","title":"A pedometer or step counter","detail":"Pick up a basic step counter and track your day. Aim for a bit more than yesterday, not a perfect number."},{"id":"fitness-33","category":"fitness","budget":"low","kind":"do","title":"Ice skates from a thrift shop","detail":"Check a thrift or consignment shop for used skates in your size. Pair with an outing if a rink is nearby."},{"id":"fitness-34","category":"fitness","budget":"low","kind":"do","title":"Thermal gloves and a walking date","detail":"Treat yourself to a pair of warm gloves, then invite a friend for a winter walk. Chat the whole way."},{"id":"fitness-35","category":"fitness","budget":"medium","kind":"do","title":"Go ice skating","detail":"Rent skates and spend an hour at a local rink. Hold the wall if you need it and cheer each other on."},{"id":"fitness-36","category":"fitness","budget":"medium","kind":"do","title":"A drop in yoga class","detail":"Try a beginner yoga class at a studio or community center. Tell the teacher it is your first time."},{"id":"fitness-37","category":"fitness","budget":"medium","kind":"do","title":"An indoor climbing day pass","detail":"Try a beginner session at a climbing gym with rented shoes and a quick lesson. Enjoy the view from the lower walls."},{"id":"fitness-38","category":"fitness","budget":"medium","kind":"do","title":"A swim and sauna visit","detail":"Buy a pool day pass for a gentle swim or water walk, and finish in the sauna or hot tub if the facility has one."},{"id":"fitness-39","category":"fitness","budget":"medium","kind":"do","title":"Rent snowshoes for an easy trail","detail":"Rent snowshoes at a local outfitter and walk a flat, marked trail. Pack a thermos and take your time."},{"id":"fitness-40","category":"fitness","budget":"medium","kind":"do","title":"A tubing or sledding park","detail":"Visit a snow tubing hill for an afternoon of sliding and short climbs. Wear layers and pace yourself."},{"id":"fitness-41","category":"fitness","budget":"high","kind":"do","title":"A beginner ski or snowboard lesson","detail":"Book a group lesson at a nearby hill. Instructors start with the basics, so you can try it safely."},{"id":"fitness-42","category":"fitness","budget":"high","kind":"do","title":"A trial with a personal trainer","detail":"Book a session or two with a trainer for a safe starter plan. Mention any aches so they can adjust."},{"id":"fitness-43","category":"fitness","budget":"high","kind":"do","title":"A month at a gym or studio","detail":"Sign up for a one month membership at a gym or studio and try three different classes. Keep the one you enjoy."},{"id":"fitness-44","category":"fitness","budget":"high","kind":"do","title":"Quality winter walking gear","detail":"Invest in waterproof boots or a warm shell you would happily wear all season, and test them on a long walk."},{"id":"music-01","category":"music","budget":"none","kind":"do","title":"Sing one carol out loud","detail":"Pick a carol everyone half knows and sing it together, even if the words wobble. Applause is mandatory."},{"id":"music-02","category":"music","budget":"none","kind":"do","title":"Make a family playlist","detail":"Each person adds two songs to a shared playlist. Play it during dinner and guess who added what."},{"id":"music-03","category":"music","budget":"none","kind":"do","title":"Listen to an album with eyes closed","detail":"Put on a favorite holiday album, lie back, and close your eyes. Hear one new detail in a familiar song."},{"id":"music-04","category":"music","budget":"none","kind":"do","title":"Build kitchen shakers","detail":"Fill empty jars or tins with rice, beans, or buttons and shake along to a favorite song. Try different fillings for different sounds."},{"id":"music-05","category":"music","budget":"none","kind":"think","title":"The song that smells like childhood","detail":"Which song instantly takes you back to a childhood winter? Share it with someone and tell them where you were."},{"id":"music-06","category":"music","budget":"none","kind":"do","title":"Hum that tune","detail":"One person hums a holiday tune with no words. Everyone else guesses the song, then switches."},{"id":"music-07","category":"music","budget":"none","kind":"do","title":"Spin the wheel of genres","detail":"Write five genres on slips. Draw one and play a tune in that style on any instrument, pot, or table."},{"id":"music-08","category":"music","budget":"none","kind":"read","title":"Fun fact: Jingle Bells","detail":"\"Jingle Bells\" was published in 1857 as a sleigh song, and in 1965 it became one of the first songs played in space. Hum it once."},{"id":"music-09","category":"music","budget":"none","kind":"do","title":"Learn the first line of a new carol","detail":"Look up a carol you have never learned and memorize its first verse. Teach it to someone else tonight."},{"id":"music-10","category":"music","budget":"none","kind":"do","title":"Lullaby time","detail":"Sing a gentle lullaby to a child, a pet, or yourself. Hum it softly if you forget the words."},{"id":"music-11","category":"music","budget":"none","kind":"do","title":"Silent disco in the kitchen","detail":"Everyone wears earbuds with their own song and dances in the same room. See who is out of step."},{"id":"music-12","category":"music","budget":"none","kind":"do","title":"Call and response clapping","detail":"One person claps a rhythm and the others copy it back. Make it longer each round until someone slips."},{"id":"music-13","category":"music","budget":"none","kind":"think","title":"If your life had a winter soundtrack","detail":"Pick three songs that would play while you shovel snow, open gifts, and lie on the couch. Say why."},{"id":"music-14","category":"music","budget":"none","kind":"do","title":"A voice warm up","detail":"Hum low, then high, then slide between them like a siren. Do five rounds, then sing your favorite song."},{"id":"music-15","category":"music","budget":"none","kind":"do","title":"Name that decade","detail":"Play snippets of old holiday songs and guess the decade each came from. Keep score with a pencil."},{"id":"music-16","category":"music","budget":"none","kind":"do","title":"Tap out a rhythm on glasses","detail":"Fill glasses with different levels of water, tap with a spoon, and play the first line of a simple song."},{"id":"music-17","category":"music","budget":"none","kind":"read","title":"A tiny verse about snow","detail":"Snow on the roof and snow on the street, / soft little music for tired feet. / Hush goes the world and the night turns slow, / sing something low for the falling snow."},{"id":"music-18","category":"music","budget":"none","kind":"do","title":"Learn a rhythm with your feet","detail":"Stomp, stomp, clap. Add a snap at the end. Repeat it for two minutes and call it your family beat."},{"id":"music-19","category":"music","budget":"none","kind":"do","title":"Music box memories","detail":"Ask each person to share a song that was played at a special moment in their life. Listen to each one together."},{"id":"music-20","category":"music","budget":"none","kind":"do","title":"Write new words to a familiar tune","detail":"Write a silly verse about your own house to a tune everyone knows. Sing it at dinner."},{"id":"music-21","category":"music","budget":"none","kind":"do","title":"Instrument swap","detail":"Switch instruments or voices with someone in the family. Play something simple on whatever you can find."},{"id":"music-22","category":"music","budget":"none","kind":"do","title":"Listen to a classical winter piece","detail":"Look up a piece inspired by winter, like Vivaldi's Winter or Tchaikovsky's Nutcracker suite, and listen end to end."},{"id":"music-23","category":"music","budget":"none","kind":"think","title":"One song you never skip","detail":"Which holiday song do you let play every time it comes on? What is it about the sound that holds you?"},{"id":"music-24","category":"music","budget":"none","kind":"do","title":"Dance the slowest dance","detail":"Pick a slow song and sway in the kitchen with someone. Hold still for the last chorus."},{"id":"music-25","category":"music","budget":"low","kind":"do","title":"A kazoo band","detail":"Buy a few kazoos for a couple of dollars each and hum a carol as a trio. Try a round."},{"id":"music-26","category":"music","budget":"low","kind":"do","title":"A harmonica to try","detail":"Pick up an inexpensive harmonica and learn to play three notes. Breathe in and out softly."},{"id":"music-27","category":"music","budget":"low","kind":"do","title":"Play A Charlie Brown Christmas","detail":"Download or stream the Vince Guaraldi Trio's classic album and listen to the whole thing with the lights low."},{"id":"music-28","category":"music","budget":"low","kind":"do","title":"Hand percussion for everyone","detail":"Buy shakers, tambourines, or bells and play along with a holiday song. Pass them around in a circle."},{"id":"music-29","category":"music","budget":"low","kind":"do","title":"A tin whistle or recorder","detail":"Buy a recorder or tin whistle and learn the first four notes of a simple carol from an online chart."},{"id":"music-30","category":"music","budget":"low","kind":"do","title":"Karaoke night at home","detail":"Use a free karaoke video and pick songs everyone knows. Give out a paper trophy for most dramatic ending."},{"id":"music-31","category":"music","budget":"low","kind":"do","title":"Sheet music for a simple carol","detail":"Print or buy a simple arrangement of a carol and try playing it on any keyboard or instrument you can find."},{"id":"music-32","category":"music","budget":"low","kind":"do","title":"A new playlist, a new album","detail":"Buy or stream one album you have never listened to, in a style you do not usually enjoy, and play it from start to finish."},{"id":"music-33","category":"music","budget":"low","kind":"do","title":"Jingle bells for the dog or door","detail":"Buy a string of bells and hang them on the door so every entrance gets a happy jingle."},{"id":"music-34","category":"music","budget":"low","kind":"do","title":"A used vinyl find","detail":"Visit a thrift store or record shop and pick one record by cover alone. Play it when you get home."},{"id":"music-35","category":"music","budget":"medium","kind":"do","title":"A ukulele to learn","detail":"Buy a beginner ukulele and learn two chords. It is the friendliest instrument for a first holiday sing along."},{"id":"music-36","category":"music","budget":"medium","kind":"do","title":"A community sing along","detail":"Find a local holiday sing along, choir concert, or carol night. Join in on the choruses."},{"id":"music-37","category":"music","budget":"medium","kind":"do","title":"Tickets to a local concert","detail":"Check a local venue, school, or library for an inexpensive holiday concert and make an outing of it."},{"id":"music-38","category":"music","budget":"medium","kind":"do","title":"A portable speaker","detail":"Pick up a small Bluetooth speaker and carry it from room to room as the soundtrack to chores, cooking, and tree trimming."},{"id":"music-39","category":"music","budget":"medium","kind":"do","title":"A keyboard for beginners","detail":"Buy a small used keyboard and learn a simple melody. Ten minutes a day brings a surprising amount of progress."},{"id":"music-40","category":"music","budget":"medium","kind":"do","title":"A one month music lesson trial","detail":"Book a few lessons for guitar, piano, or voice. Ask the teacher to teach a favorite holiday song."},{"id":"music-41","category":"music","budget":"high","kind":"do","title":"Symphony or ballet tickets","detail":"Treat yourself and someone you love to a holiday concert or ballet by a professional company. Dress up for it."},{"id":"music-42","category":"music","budget":"high","kind":"do","title":"A real instrument for your home","detail":"Invest in a decent guitar, piano, or drum set you will keep for years. Play something small every day."},{"id":"music-43","category":"music","budget":"high","kind":"do","title":"Good headphones","detail":"Splurge on a pair of comfortable, good sounding headphones and spend an evening revisiting your favorite albums."},{"id":"music-44","category":"music","budget":"high","kind":"do","title":"A multi month lesson package","detail":"Sign up for a series of lessons in voice, piano, or guitar. Put the first lesson on the calendar today."},{"id":"puzzles-01","category":"puzzles","budget":"none","kind":"think","title":"What has hands but cannot clap?","detail":"A winter evening riddle. It sits on a wall or a wrist and marks every minute of the holiday rush. What is it?","reveal":"A clock."},{"id":"puzzles-02","category":"puzzles","budget":"none","kind":"think","title":"I get wetter as I dry","detail":"You use me after every bath, and you hang me on a hook. The more I work, the wetter I become. What am I?","reveal":"A towel."},{"id":"puzzles-03","category":"puzzles","budget":"none","kind":"think","title":"Cities with no houses","detail":"I have cities but no houses, mountains but no trees, and water but no fish. What am I?","reveal":"A map."},{"id":"puzzles-04","category":"puzzles","budget":"none","kind":"think","title":"The tall thin candle","detail":"I am tall when I am young and short when I am old. I give light, but I shrink while I do. What am I?","reveal":"A candle."},{"id":"puzzles-05","category":"puzzles","budget":"none","kind":"think","title":"The decorated guest","detail":"I have needles but never sew. I wear lights but never glow on my own. I stand in the living room. What am I?","reveal":"A Christmas tree."},{"id":"puzzles-06","category":"puzzles","budget":"none","kind":"think","title":"Count the gifts","detail":"On the twelve days of Christmas song, a person receives gifts that add up each day. How many gifts do they get in total over all twelve days?","reveal":"364. Day n brings n(n+1)/2 gifts, and twelve days of those add to 364."},{"id":"puzzles-07","category":"puzzles","budget":"none","kind":"think","title":"Three generations go fishing","detail":"Two fathers and two sons go fishing. Each catches one fish and the total is three. How can that be?","reveal":"There are three people: a grandfather, his son, and his grandson."},{"id":"puzzles-08","category":"puzzles","budget":"none","kind":"think","title":"Which month has 28 days?","detail":"A quick trick question for the dinner table. How many months of the year have 28 days?","reveal":"All twelve of them."},{"id":"puzzles-09","category":"puzzles","budget":"none","kind":"think","title":"Pound of feathers or pound of coins?","detail":"Which is heavier, a pound of feathers or a pound of coins? Answer fast, then think again.","reveal":"Neither. A pound is a pound."},{"id":"puzzles-10","category":"puzzles","budget":"none","kind":"think","title":"The snail in the well","detail":"A snail climbs 3 feet up a 10 foot well each day and slides back 2 feet each night. On which day does it get out?","reveal":"Day 8. It starts day 8 at 7 feet and climbs the last 3."},{"id":"puzzles-11","category":"puzzles","budget":"none","kind":"think","title":"Word ladder: COLD to WARM","detail":"Change one letter at a time to turn COLD into WARM. Each step must be a real word. How many steps can you do it in?","reveal":"COLD, CORD, CARD, WARD, WARM (four steps)."},{"id":"puzzles-12","category":"puzzles","budget":"none","kind":"think","title":"Think of a number","detail":"Think of any number, double it, add 10, halve that, then subtract your starting number. What is your answer?","reveal":"Always 5. The starting number cancels out."},{"id":"puzzles-13","category":"puzzles","budget":"none","kind":"think","title":"A letter in a minute","detail":"What appears once in a minute, twice in a moment, but never in a thousand years?","reveal":"The letter M."},{"id":"puzzles-14","category":"puzzles","budget":"none","kind":"think","title":"Thirteen hearts","detail":"I have thirteen hearts but no other organs. You deal me out on a table in the evening. What am I?","reveal":"A deck of cards."},{"id":"puzzles-15","category":"puzzles","budget":"none","kind":"think","title":"The traveling stamp","detail":"I can travel around the world while staying stuck in the corner. What am I?","reveal":"A postage stamp."},{"id":"puzzles-16","category":"puzzles","budget":"none","kind":"think","title":"Forward heavy, backward not","detail":"Forward I am heavy. Backward I am not. What word am I?","reveal":"Ton (backward it spells \"not\")."},{"id":"puzzles-17","category":"puzzles","budget":"none","kind":"think","title":"The tall building with stories","detail":"What building has the most stories, none of them tall tales?","reveal":"A library."},{"id":"puzzles-18","category":"puzzles","budget":"none","kind":"think","title":"All but nine","detail":"A farmer has 17 sheep and all but 9 wander off. How many sheep does he have left?","reveal":"Nine."},{"id":"puzzles-19","category":"puzzles","budget":"none","kind":"do","title":"Draw a maze for someone","detail":"Draw a maze on paper with a start and finish, then hand it to someone else to solve. Add a few dead ends and a snowman as the goal."},{"id":"puzzles-20","category":"puzzles","budget":"none","kind":"do","title":"Anagram snow day","detail":"Write SILENT on a card and see who spots the swap into LISTEN first. Then create a pair of your own."},{"id":"puzzles-21","category":"puzzles","budget":"none","kind":"do","title":"Tic tac toe snow tournament","detail":"Play tic tac toe with candy canes (or X and O drawn in steam on a window). Best of five wins."},{"id":"puzzles-22","category":"puzzles","budget":"none","kind":"think","title":"Next in the sequence","detail":"What number comes next? 1, 1, 2, 3, 5, 8, 13, ...","reveal":"21. Each number is the sum of the two before it."},{"id":"puzzles-23","category":"puzzles","budget":"none","kind":"do","title":"Twenty questions, winter edition","detail":"One person thinks of something winter themed. The others have 20 yes or no questions to guess it."},{"id":"puzzles-24","category":"puzzles","budget":"none","kind":"think","title":"Two apples","detail":"If you have three apples and take away two, how many apples do you have?","reveal":"Two. You took two, so those are the ones you have."},{"id":"puzzles-25","category":"puzzles","budget":"low","kind":"do","title":"A crossword puzzle book","detail":"Buy a small crossword or word search book and do one page together. Pass the pencil when stuck."},{"id":"puzzles-26","category":"puzzles","budget":"low","kind":"do","title":"A 300 piece jigsaw","detail":"Pick up a small winter scene jigsaw and set it up on a tray so it is easy to move. Start with the edges."},{"id":"puzzles-27","category":"puzzles","budget":"low","kind":"do","title":"A classic Rubik's cube","detail":"Buy a basic cube and try to solve one face. Search for a beginner's method if you want a guide."},{"id":"puzzles-28","category":"puzzles","budget":"low","kind":"do","title":"A sudoku book and a pencil","detail":"Buy a book of beginner sudoku puzzles and work one each night this week."},{"id":"puzzles-29","category":"puzzles","budget":"low","kind":"do","title":"A wooden brain teaser","detail":"Pick up a wooden or metal disentanglement puzzle for a few dollars. Pass it around the table and see who can solve it."},{"id":"puzzles-30","category":"puzzles","budget":"low","kind":"do","title":"A cryptogram book","detail":"Find a book of cryptograms where each letter stands for another. Solve a short quote together."},{"id":"puzzles-31","category":"puzzles","budget":"low","kind":"do","title":"Pocket puzzle stocking stuffers","detail":"Buy small puzzles like mazes, riddle cards, or mini jigsaws, and slip one in every stocking."},{"id":"puzzles-32","category":"puzzles","budget":"low","kind":"do","title":"A Mad Gab or rebus pad","detail":"Buy a puzzle pad of picture riddles and read them out loud. The sillier the answer, the better."},{"id":"puzzles-33","category":"puzzles","budget":"low","kind":"do","title":"A logic grid puzzle book","detail":"Buy a logic puzzle book where you deduce who owns which pet. Work one slowly with a friend."},{"id":"puzzles-34","category":"puzzles","budget":"low","kind":"do","title":"A deck of cards and solitaire rules","detail":"Buy a fresh deck of cards and learn two new solitaire games. Teach each other your favorite."},{"id":"puzzles-35","category":"puzzles","budget":"medium","kind":"do","title":"A 1000 piece jigsaw","detail":"Buy a 1000 piece puzzle with a cozy winter scene and leave it out on a table for the month. Add a few pieces each day."},{"id":"puzzles-36","category":"puzzles","budget":"medium","kind":"do","title":"An escape room in a box","detail":"Buy a boxed escape room game and play it through with the family. Set a one hour timer."},{"id":"puzzles-37","category":"puzzles","budget":"medium","kind":"do","title":"A mystery game for the table","detail":"Pick up a murder mystery or detective board game and play a round with friends. Have an accomplice ready."},{"id":"puzzles-38","category":"puzzles","budget":"medium","kind":"do","title":"A 3D wooden puzzle","detail":"Buy a wooden model puzzle that snaps together without glue. Build it over a few evenings."},{"id":"puzzles-39","category":"puzzles","budget":"medium","kind":"do","title":"A word game for the family","detail":"Buy a classic word game or a new one and play a quick round after dinner. Allow dictionary challenges."},{"id":"puzzles-40","category":"puzzles","budget":"medium","kind":"do","title":"A custom photo puzzle","detail":"Order a small jigsaw printed with a family photo. Surprise a loved one with a puzzle of themselves."},{"id":"puzzles-41","category":"puzzles","budget":"high","kind":"do","title":"A real escape room","detail":"Book a local escape room for your family or friends. Choose one with a gentle theme and a good clue helper."},{"id":"puzzles-42","category":"puzzles","budget":"high","kind":"do","title":"A murder mystery dinner night","detail":"Book a murder mystery dinner or host one with a purchased kit and costumes. Assign characters in advance."},{"id":"puzzles-43","category":"puzzles","budget":"high","kind":"do","title":"A big custom puzzle","detail":"Order a large 1500 or 2000 piece jigsaw printed with a favorite photo and set it up where everyone can add pieces."},{"id":"puzzles-44","category":"puzzles","budget":"high","kind":"do","title":"A puzzle hunt adventure","detail":"Book a guided city puzzle hunt or treasure hunt tour with friends. Wear comfortable shoes and bring a notepad."},{"id":"food-01","category":"food","budget":"none","kind":"do","title":"Cinnamon sugar toast","detail":"Butter a slice of toast, sprinkle on cinnamon and sugar, and toast it again until the edges crisp. Eat it warm, slowly."},{"id":"food-02","category":"food","budget":"none","kind":"do","title":"Breakfast for dinner","detail":"Make pancakes, eggs, or oatmeal for dinner tonight and eat by candlelight. Let the youngest pick the toppings."},{"id":"food-03","category":"food","budget":"none","kind":"do","title":"Fridge raid soup","detail":"Simmer whatever vegetables, rice, or noodles you already have into a warm soup. Season it as you go and name it after the day."},{"id":"food-04","category":"food","budget":"none","kind":"do","title":"Popcorn garland","detail":"Pop a batch of plain popcorn, thread it on string with a needle, and drape it on the tree or window. Share the leftovers."},{"id":"food-05","category":"food","budget":"none","kind":"do","title":"Pancake shapes","detail":"Pour pancake batter into shapes like stars, hearts, and snowmen. Eat the best one first, and save the worst for the cook."},{"id":"food-06","category":"food","budget":"none","kind":"do","title":"Orange peel decorations","detail":"Peel an orange in long curls, or cut out stars from the peel, and let them dry on a windowsill for a citrus scent."},{"id":"food-07","category":"food","budget":"none","kind":"think","title":"Your favorite holiday dish","detail":"What dish tastes like the holidays to you? Who made it first, and what small trick made it theirs?"},{"id":"food-08","category":"food","budget":"none","kind":"read","title":"Grandma's recipe on a card","detail":"Write a favorite family recipe on a card with notes about who loved it. Add it to the recipe box or tape it inside a cupboard."},{"id":"food-09","category":"food","budget":"none","kind":"do","title":"Indoor picnic dinner","detail":"Spread a blanket on the floor, set out plates, light a candle, and eat dinner like a picnic. Pretend it is summer if you like."},{"id":"food-10","category":"food","budget":"none","kind":"do","title":"A homemade snow cream","detail":"If you have clean fresh snow, mix it with milk and sugar for a cold treat. No snow? Use crushed ice."},{"id":"food-11","category":"food","budget":"none","kind":"do","title":"Bread and butter tasting","detail":"Compare toast with different spreads you have at home. Rate each from one to five and crown a champion."},{"id":"food-12","category":"food","budget":"none","kind":"do","title":"Cook with the kid in charge","detail":"Let a child choose the menu from what's in the kitchen and direct the cooking. Adults act as assistants."},{"id":"food-13","category":"food","budget":"none","kind":"do","title":"Make toast snowmen","detail":"Use a round cookie cutter or a cup to cut bread circles, stack two or three, and decorate with whatever you have in the fridge."},{"id":"food-14","category":"food","budget":"none","kind":"do","title":"Warm milk with honey","detail":"Heat a cup of milk with a spoonful of honey and a dash of cinnamon. Sip it slowly before bedtime."},{"id":"food-15","category":"food","budget":"none","kind":"do","title":"A taste test with eyes closed","detail":"Blindfold a family member and have them guess five foods from the pantry by taste and smell. Swap turns."},{"id":"food-16","category":"food","budget":"none","kind":"do","title":"Cook one meal from memory","detail":"Make a dish you remember from childhood without a recipe, relying on taste. Tell the story behind it as you eat."},{"id":"food-17","category":"food","budget":"none","kind":"do","title":"Set the table like a restaurant","detail":"Fold napkins, light candles, and write a menu on a card. One person is the waiter for the evening."},{"id":"food-18","category":"food","budget":"none","kind":"think","title":"The smell of your grandmother's kitchen","detail":"What smells fill your memory of a holiday kitchen? Share what you can still taste."},{"id":"food-19","category":"food","budget":"none","kind":"do","title":"Leftover remix night","detail":"Combine the leftovers into something new, like fried rice, quesadillas, or a savory hash. Give the dish a silly name."},{"id":"food-20","category":"food","budget":"none","kind":"do","title":"Juice snow cones","detail":"Fill a small cup with crushed ice or clean snow and pour juice over it. Eat it with a spoon while watching the weather."},{"id":"food-21","category":"food","budget":"none","kind":"do","title":"Roast something simple","detail":"Roast potatoes, carrots, or squash in the oven with oil and salt. Notice how the house smells as they cook."},{"id":"food-22","category":"food","budget":"none","kind":"do","title":"Pantry spice sniff test","detail":"Close your eyes while someone holds open spice jars one at a time. Guess each one by smell alone, then taste a pinch if you like."},{"id":"food-23","category":"food","budget":"none","kind":"do","title":"Share a recipe over the phone","detail":"Call a relative and ask for their favorite recipe. Write it down exactly as they say it, including the quirks."},{"id":"food-24","category":"food","budget":"none","kind":"do","title":"Rice pudding on the stove","detail":"Simmer leftover rice with milk, sugar, and cinnamon until creamy. Eat it warm with a spoon."},{"id":"food-25","category":"food","budget":"low","kind":"do","title":"A gingerbread house kit","detail":"Buy a small gingerbread house kit and build it together. Eat the evidence at the end."},{"id":"food-26","category":"food","budget":"low","kind":"do","title":"Sugar cookie decorating","detail":"Buy plain sugar cookies or dough, plus frosting and sprinkles, and decorate one for each family member."},{"id":"food-27","category":"food","budget":"low","kind":"do","title":"Chocolate fondue night","detail":"Melt chocolate chips with a splash of cream in a pot and dip fruit, pretzels, and marshmallows into it."},{"id":"food-28","category":"food","budget":"low","kind":"do","title":"A fresh bakery loaf","detail":"Buy a warm loaf of crusty bread from a bakery. Eat the first piece standing right at the counter."},{"id":"food-29","category":"food","budget":"low","kind":"do","title":"Spiced nuts","detail":"Toss walnuts or pecans with cinnamon, sugar, and a pinch of salt. Bake until fragrant and pack them in jars."},{"id":"food-30","category":"food","budget":"low","kind":"do","title":"A fruit you have never tried","detail":"Pick one unusual fruit from the market, like a pomegranate or a persimmon, and taste it together."},{"id":"food-31","category":"food","budget":"low","kind":"do","title":"Hot cocoa with real toppings","detail":"Buy marshmallows, whipped cream, or crushed peppermint and set up a toppings bar. Everyone builds their own cup."},{"id":"food-32","category":"food","budget":"low","kind":"do","title":"Make homemade pizza","detail":"Buy dough or flatbread, sauce, and cheese. Let everyone top their own and bake until bubbly."},{"id":"food-33","category":"food","budget":"low","kind":"do","title":"A box of tea samplers","detail":"Buy a sampler of herbal teas and try a new one each night this week. Rate your favorites."},{"id":"food-34","category":"food","budget":"low","kind":"do","title":"Candy cane bark","detail":"Melt chocolate and spread it thin, then sprinkle crushed candy canes on top. Chill and break into pieces."},{"id":"food-35","category":"food","budget":"medium","kind":"do","title":"A cheese and cracker board","detail":"Build a board with three cheeses, crackers, fruit, and nuts. Eat slowly and compare tastes."},{"id":"food-36","category":"food","budget":"medium","kind":"do","title":"Dinner at a cozy diner","detail":"Take your family or a friend to a classic diner for breakfast or dinner. Order something you would not make at home."},{"id":"food-37","category":"food","budget":"medium","kind":"do","title":"A box of local pastries","detail":"Visit a good bakery and pick a box of pastries to share. Each person chooses one for another."},{"id":"food-38","category":"food","budget":"medium","kind":"do","title":"A DIY pasta night","detail":"Buy fresh pasta and a good sauce, and make a simple meal for friends. Add a salad and a crusty bread."},{"id":"food-39","category":"food","budget":"medium","kind":"do","title":"A cooking kit to try","detail":"Buy a meal kit or ingredient set for a dish you have never made, such as dumplings or paella, and cook it together."},{"id":"food-40","category":"food","budget":"medium","kind":"do","title":"A nice chocolate tasting","detail":"Buy three bars of fine chocolate and taste them slowly side by side. Pass them around and describe flavors."},{"id":"food-41","category":"food","budget":"high","kind":"do","title":"A tasting menu dinner","detail":"Reserve a table for a multi course tasting menu at a restaurant you have always wanted to try. Dress nicely for it."},{"id":"food-42","category":"food","budget":"high","kind":"do","title":"A cooking class for two","detail":"Book a hands on cooking class together. Learn one technique that you will use every week."},{"id":"food-43","category":"food","budget":"high","kind":"do","title":"A holiday dinner spread","detail":"Splurge on a spiral ham, a good roast, or a seafood platter for the table. Set it with real candles."},{"id":"food-44","category":"food","budget":"high","kind":"do","title":"A gourmet gift basket to share","detail":"Order a gift box of fine cheeses, chocolates, and jams, and enjoy it as a family over several nights."},{"id":"humor-01","category":"humor","budget":"none","kind":"think","title":"What do snowmen eat for breakfast?","detail":"Here is a cold open to start the morning. Ask someone at the table and wait for the groan.","reveal":"Frosted flakes."},{"id":"humor-02","category":"humor","budget":"none","kind":"think","title":"Why do Christmas trees like the past?","detail":"A classic wordplay riddle to try on the family. Give them a moment to guess before the answer.","reveal":"Because the present is always under them."},{"id":"humor-03","category":"humor","budget":"none","kind":"think","title":"How does a snowman get around?","detail":"Ask this one quietly, then let the room think about the transportation options.","reveal":"By icicle."},{"id":"humor-04","category":"humor","budget":"none","kind":"think","title":"What do you call a dog in the snow?","detail":"This one goes best at the dinner table with a straight face.","reveal":"A pup-sicle."},{"id":"humor-05","category":"humor","budget":"none","kind":"think","title":"What do you call an old snowman?","detail":"Offer this with a sigh and a long pause for dramatic effect.","reveal":"Water."},{"id":"humor-06","category":"humor","budget":"none","kind":"think","title":"What is an elf's favorite kind of music?","detail":"Ask this on a tree trimming day with a hammy delivery.","reveal":"Wrap music."},{"id":"humor-07","category":"humor","budget":"none","kind":"think","title":"Why did Santa go to music school?","detail":"Tell this one in your best radio voice and wait for the groan.","reveal":"To improve his wrap skills."},{"id":"humor-08","category":"humor","budget":"none","kind":"think","title":"What do you call a snowman in July?","detail":"A short one, perfect for the car ride or the walk to the mailbox.","reveal":"A puddle."},{"id":"humor-09","category":"humor","budget":"none","kind":"think","title":"Why was the cookie sent to the nurse?","detail":"Tell this at the baking table while the cookies cool.","reveal":"It was feeling crummy."},{"id":"humor-10","category":"humor","budget":"none","kind":"think","title":"What did one snowman say to the other?","detail":"Two snowmen are standing in the yard on a crisp morning. One turns and whispers something. What does he say?","reveal":"Do you smell carrots?"},{"id":"humor-11","category":"humor","budget":"none","kind":"do","title":"Hold a pun contest","detail":"Take five minutes to invent holiday puns. Everyone votes for the worst and the best, and the worst winner gets a paper crown."},{"id":"humor-12","category":"humor","budget":"none","kind":"do","title":"Narrate your day like a nature show","detail":"Describe your morning in a hushed documentary voice. \"Here, the human reaches for the coffee...\" Record it on a phone."},{"id":"humor-13","category":"humor","budget":"none","kind":"do","title":"Dramatic reading of a grocery list","detail":"Read the shopping list like it's an epic poem. Add a heroic voice and a slow dramatic pause between each item."},{"id":"humor-14","category":"humor","budget":"none","kind":"do","title":"Reindeer impressions","detail":"Everyone gets thirty seconds to do their best reindeer. Judge on antlers, nose, and snort. Videos are encouraged."},{"id":"humor-15","category":"humor","budget":"none","kind":"do","title":"Silliest gift pitch","detail":"Each person makes a thirty second sales pitch for a ridiculous imaginary gift, like a pocket snowstorm or a self wrapping sock."},{"id":"humor-16","category":"humor","budget":"none","kind":"do","title":"Rename holiday movies","detail":"Make up silly new titles for famous holiday films, like \"Home Alone but With Dad.\" Vote for the funniest."},{"id":"humor-17","category":"humor","budget":"none","kind":"do","title":"Tell a bad dad joke on purpose","detail":"Share your worst pun at dinner and let the family vote on the groan level, from one to ten."},{"id":"humor-18","category":"humor","budget":"none","kind":"do","title":"Oral Mad Libs","detail":"One person asks for a noun, verb, and adjective and fills them into a short story. Read the finished story aloud."},{"id":"humor-19","category":"humor","budget":"none","kind":"read","title":"A short silly verse","detail":"Said the snowman to the snowy wind, / \"Please go easy, I am thinly pinned.\" / The wind said, \"Sorry, friend, I hate to fuss,\" / and gave him a hat of icy fuzz."},{"id":"humor-20","category":"humor","budget":"none","kind":"do","title":"Funny family movie reenactment","detail":"Pick a scene from a family movie and act it out with whatever props are in the house. Keep it under three minutes."},{"id":"humor-21","category":"humor","budget":"none","kind":"do","title":"Accent challenge","detail":"Order dinner or ask for the salt in a silly accent. See who can hold it longest without laughing."},{"id":"humor-22","category":"humor","budget":"none","kind":"do","title":"Make up a ridiculous holiday","detail":"Invent a holiday like \"Mismatched Sock Day\" and write three traditions for it. Celebrate for ten minutes today."},{"id":"humor-23","category":"humor","budget":"none","kind":"read","title":"A reindeer fun fact","detail":"Reindeer eyes change from golden in summer to blue in winter, which helps them see in the dim Arctic light. Share it at dinner like you knew all along."},{"id":"humor-24","category":"humor","budget":"none","kind":"do","title":"Pillow fight (the gentle kind)","detail":"Clear the room and use soft cushions only. Set rules: no faces, no walls, and the first giggle loses a point."},{"id":"humor-25","category":"humor","budget":"low","kind":"do","title":"A joke book for the stockings","detail":"Buy a small joke book and slip it into a stocking. Read three out loud on the morning after."},{"id":"humor-26","category":"humor","budget":"low","kind":"do","title":"Funny socks for everyone","detail":"Find silly socks with reindeer, pizza, or cats, and wear them for the whole day. Compare patterns at lunch."},{"id":"humor-27","category":"humor","budget":"low","kind":"do","title":"A Mad Libs pad","detail":"Pick up a Mad Libs pad and play in pairs, then read the finished stories aloud at dinner."},{"id":"humor-28","category":"humor","budget":"low","kind":"do","title":"Fake mustaches and a mirror","detail":"Buy a pack of fake mustaches, wear them through one family meal, and see who forgets first."},{"id":"humor-29","category":"humor","budget":"low","kind":"do","title":"Silly hats for dinner","detail":"Buy cheap party hats or reindeer antlers and wear them at dinner. Take a serious family portrait in them."},{"id":"humor-30","category":"humor","budget":"low","kind":"do","title":"A sticker pack of terrible puns","detail":"Find stickers or cards with groan worthy puns and tuck them into surprising places around the house."},{"id":"humor-31","category":"humor","budget":"low","kind":"do","title":"A gag gift exchange","detail":"Set a five dollar limit and buy the funniest gift you can find. Open them in turn and rate them."},{"id":"humor-32","category":"humor","budget":"low","kind":"do","title":"A game of Taboo or Charades cards","detail":"Buy a pack of party cards and play two rounds of silly clues. Dramatic acting is part of the fun."},{"id":"humor-33","category":"humor","budget":"low","kind":"do","title":"Googly eyes everywhere","detail":"Buy a pack of googly eyes and stick them on the fridge, the pet, and the tree. Do a walk through to count them."},{"id":"humor-34","category":"humor","budget":"low","kind":"do","title":"A comedy movie rental","detail":"Rent a comedy that always makes someone laugh and watch it together with popcorn. Pause for the best lines."},{"id":"humor-35","category":"humor","budget":"medium","kind":"do","title":"A comedy club night","detail":"Book tickets to a comedy club or local stand up show and enjoy a night of live laughs. Check the audience rating first."},{"id":"humor-36","category":"humor","budget":"medium","kind":"do","title":"An improv show","detail":"See a local improv troupe and play along with their audience suggestions. Shout out the weirdest idea you can."},{"id":"humor-37","category":"humor","budget":"medium","kind":"do","title":"A silly board game night","detail":"Buy a party game known for laughs, like a drawing, charades, or bluffing game, and play a long round."},{"id":"humor-38","category":"humor","budget":"medium","kind":"do","title":"An ugly sweater for the season","detail":"Buy or swap for a gloriously tacky sweater and wear it all week. Bring a spare for a friend."},{"id":"humor-39","category":"humor","budget":"medium","kind":"do","title":"A funny movie night out","detail":"See a comedy at the theater with snacks. Rate each laugh on a scale of one to five afterward."},{"id":"humor-40","category":"humor","budget":"medium","kind":"do","title":"A drop in laughter or improv class","detail":"Sign up for a beginner improv workshop and laugh at yourself. Wear comfortable clothes and say yes to everything."},{"id":"humor-41","category":"humor","budget":"high","kind":"do","title":"Front row comedy tickets","detail":"Splurge on good seats at a comedy show for two or a small group, with dinner beforehand to make a proper night of it."},{"id":"humor-42","category":"humor","budget":"high","kind":"do","title":"A six week improv course","detail":"Enroll in a short improv or sketch comedy course. The final performance is the best part."},{"id":"humor-43","category":"humor","budget":"high","kind":"do","title":"A group comedy outing","detail":"Book tickets for friends or family to a big touring comedian and go to dinner beforehand. Split the cost if needed."},{"id":"humor-44","category":"humor","budget":"high","kind":"do","title":"A private comedy night at home","detail":"Hire a local comedian or improv group to perform at your holiday party. Ask for a clean family set."},{"id":"books-01","category":"books","budget":"none","kind":"do","title":"Visit the library","detail":"Walk to the library and wander the shelves without a plan. Check out one book because of its cover alone."},{"id":"books-02","category":"books","budget":"none","kind":"read","title":"A Visit from St. Nicholas aloud","detail":"Read the 1823 poem \"A Visit from St. Nicholas\" aloud with your best storyteller voice. It is free to find online and takes five minutes."},{"id":"books-03","category":"books","budget":"none","kind":"read","title":"A Christmas Carol, Stave One","detail":"Read the first chapter of Dickens's A Christmas Carol aloud. It is public domain and free at your library or online."},{"id":"books-04","category":"books","budget":"none","kind":"read","title":"The Gift of the Magi","detail":"Read O. Henry's short story \"The Gift of the Magi\" aloud. It takes about fifteen minutes and is free online."},{"id":"books-05","category":"books","budget":"none","kind":"do","title":"Reread a childhood favorite","detail":"Pull down a book you loved as a kid and read the first chapter. Notice what you remember before the next sentence."},{"id":"books-06","category":"books","budget":"none","kind":"think","title":"The book that changed you","detail":"Which book shifted how you see things? Tell someone why, and which line you still remember."},{"id":"books-07","category":"books","budget":"none","kind":"read","title":"Stopping by Woods on a Snowy Evening","detail":"Read Robert Frost's short winter poem aloud and listen for the rhythm. It takes one minute and is easy to find online."},{"id":"books-08","category":"books","budget":"none","kind":"do","title":"Read aloud to a pet","detail":"Read a few pages aloud to a pet, a plant, or a stuffed animal. Use voices for the characters."},{"id":"books-09","category":"books","budget":"none","kind":"do","title":"Build a family reading nook","detail":"Pile blankets and pillows in a corner with a lamp and a stack of books. Take turns reading there this week."},{"id":"books-10","category":"books","budget":"none","kind":"read","title":"A tiny story, 50 words","detail":"Write or read a story with exactly 50 words about a small winter adventure. Count them out loud when finished."},{"id":"books-11","category":"books","budget":"none","kind":"do","title":"Swap books with a friend","detail":"Pick a book from your shelf and trade with a friend, neighbor, or relative. Write a short note inside the cover."},{"id":"books-12","category":"books","budget":"none","kind":"do","title":"Make a paper bookmark","detail":"Fold and decorate a bookmark with a snowflake or a winter scene, and tuck it into your current read."},{"id":"books-13","category":"books","budget":"none","kind":"read","title":"Dulce Domum, a midwinter chapter","detail":"Read the chapter \"Dulce Domum\" from Kenneth Grahame's The Wind in the Willows, a cozy tale of a mole coming home at midwinter."},{"id":"books-14","category":"books","budget":"none","kind":"think","title":"A book for your younger self","detail":"Imagine handing a book to yourself at age ten. Which one, and why that one?"},{"id":"books-15","category":"books","budget":"none","kind":"do","title":"Pick a family read aloud","detail":"Choose a chapter book and read one chapter aloud each night this month. Take turns with the voices."},{"id":"books-16","category":"books","budget":"none","kind":"read","title":"Little Women, Chapter One","detail":"Read the opening chapter of Louisa May Alcott's Little Women. It begins with four sisters on a Christmas Eve, and it is free online."},{"id":"books-17","category":"books","budget":"none","kind":"do","title":"Create a book scavenger hunt","detail":"Hide a book somewhere in the house and write three clues to find it. The finder gets to read the first page aloud."},{"id":"books-18","category":"books","budget":"none","kind":"think","title":"The first line you remember","detail":"What is a first line from a book that has stayed in your head? Share it and see if anyone can name the book."},{"id":"books-19","category":"books","budget":"none","kind":"do","title":"Reread a favorite page","detail":"Pick a favorite scene from any book and read it aloud with feeling. Choose a scene that makes you laugh or sigh."},{"id":"books-20","category":"books","budget":"none","kind":"do","title":"Bedtime story swap","detail":"Take turns telling a bedtime story to each other, made up on the spot. Include a snowstorm and a surprising guest."},{"id":"books-21","category":"books","budget":"none","kind":"read","title":"The Nutcracker and the Mouse King","detail":"Read the opening of E.T.A. Hoffmann's story, the tale behind the ballet. It is public domain and free online."},{"id":"books-22","category":"books","budget":"none","kind":"do","title":"Rearrange a bookshelf by color","detail":"Reorder one shelf by color, then just stand back. You might find a forgotten book to start tonight."},{"id":"books-23","category":"books","budget":"none","kind":"do","title":"Borrow an audiobook","detail":"Borrow an audiobook from your library app and listen while you cook or fold laundry. Pick something gentle."},{"id":"books-24","category":"books","budget":"none","kind":"read","title":"A Snowflake poem by you","detail":"Write a four line poem about the first snowfall you remember. Read it aloud to someone who will not critique it."},{"id":"books-25","category":"books","budget":"low","kind":"do","title":"A thrift store paperback","detail":"Visit a thrift store or used bookshop and buy one book for a dollar or two. Bring it home and start it that night."},{"id":"books-26","category":"books","budget":"low","kind":"do","title":"The Snowy Day by Ezra Jack Keats","detail":"Buy or borrow this picture book, a gentle story of a child's first walk in the snow, and read it aloud."},{"id":"books-27","category":"books","budget":"low","kind":"do","title":"A new bookmark and reading light","detail":"Buy a bookmark and a small clip on reading light. Treat yourself to an hour of bedtime reading."},{"id":"books-28","category":"books","budget":"low","kind":"do","title":"The Polar Express by Chris Van Allsburg","detail":"Buy a copy of this picture book and read it aloud before bed, with the lights down low and cocoa nearby."},{"id":"books-29","category":"books","budget":"low","kind":"do","title":"A reading journal","detail":"Buy a small notebook and write down every book you read this winter, with one line about how it felt."},{"id":"books-30","category":"books","budget":"low","kind":"do","title":"A children's book for a toy drive","detail":"Buy a new picture book for a children's toy drive and write a short note to tuck inside the cover."},{"id":"books-31","category":"books","budget":"low","kind":"do","title":"A poetry collection","detail":"Pick up a small poetry book and read one poem aloud each night this week. Choose a different poet each time."},{"id":"books-32","category":"books","budget":"low","kind":"do","title":"A mystery novel for the cold","detail":"Buy a cozy mystery paperback and settle in to read the first three chapters on a blustery evening."},{"id":"books-33","category":"books","budget":"low","kind":"do","title":"A book swap party","detail":"Invite friends to bring a book they love and trade. Share a sentence about why you chose each one."},{"id":"books-34","category":"books","budget":"low","kind":"do","title":"A used cookbook to browse","detail":"Buy a used cookbook and read it like a novel. Mark three recipes you want to try this winter."},{"id":"books-35","category":"books","budget":"medium","kind":"do","title":"A hardcover to keep","detail":"Treat yourself to a new hardcover by an author you love. Read it slowly, a chapter a night."},{"id":"books-36","category":"books","budget":"medium","kind":"do","title":"A three month audiobook plan","detail":"Subscribe for three months to an audiobook service and download a book to listen to on walks and chores."},{"id":"books-37","category":"books","budget":"medium","kind":"do","title":"A signed local author book","detail":"Visit a local bookstore and buy a book by a local author. Ask the staff for a favorite recommendation."},{"id":"books-38","category":"books","budget":"medium","kind":"do","title":"A book club kit for friends","detail":"Buy a copy of a book for two friends and set a date to talk about it over tea. Write three discussion questions."},{"id":"books-39","category":"books","budget":"medium","kind":"do","title":"A boxed set of classics","detail":"Buy a boxed set of short classics and read one a week through January. Put the box where you can see it."},{"id":"books-40","category":"books","budget":"medium","kind":"do","title":"A bookstore afternoon","detail":"Spend an afternoon in a bookstore with a budget and a cafe cup. Pick three books and read the first page of each."},{"id":"books-41","category":"books","budget":"high","kind":"do","title":"An e-reader for travel","detail":"Buy an e-reader that holds hundreds of books. Fill it with free classics from the library and your favorites."},{"id":"books-42","category":"books","budget":"high","kind":"do","title":"A beautiful illustrated edition","detail":"Splurge on a lovely illustrated edition of a book you adore, and keep it where it can be seen."},{"id":"books-43","category":"books","budget":"high","kind":"do","title":"A book lover's weekend away","detail":"Book a weekend at a literary town, bookstore inn, or cabin with a stack of books. Plan to read for hours."},{"id":"books-44","category":"books","budget":"high","kind":"do","title":"A custom storybook","detail":"Order a personalized storybook featuring a child or loved one as the hero. Read it aloud together."}];
